// Command tdsfixture creates a synthetic TD32 sidecar for the owned Go cpulab.
// It is a test bridge, not a Delphi symbol generator or production symbol tool.
package main

import (
	"bytes"
	"debug/pe"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/gabrielteiga/AntiPessimizerV2/internal/symbols"
)

func fixture(nm io.Reader, base uint64, code uint32) ([]byte, error) {
	// nm output is generated by the same Go toolchain that built the owned target.
	data, err := io.ReadAll(io.LimitReader(nm, 8<<20))
	if err != nil {
		return nil, err
	}
	var offset, size uint64
	for _, line := range strings.Split(string(data), "\n") {
		fields := strings.Fields(line)
		if len(fields) != 4 || fields[3] != "main.hotspot" {
			continue
		}
		address, e := strconv.ParseUint(fields[0], 16, 64)
		if e != nil {
			return nil, e
		}
		size, e = strconv.ParseUint(fields[1], 10, 32)
		if e != nil {
			return nil, e
		}
		if address < base || address-base < uint64(code) {
			return nil, errors.New("hotspot precedes code section")
		}
		offset = address - base - uint64(code)
		break
	}
	if size == 0 || offset > 1<<32-1 || size > 1<<32-offset {
		return nil, errors.New("missing or invalid main.hotspot symbol")
	}
	const name = "Lab.Hotspot"
	b := make([]byte, 96+4+1+len(name)+1+8)
	p16 := func(n int, v uint16) { binary.LittleEndian.PutUint16(b[n:], v) }
	p32 := func(n int, v uint32) { binary.LittleEndian.PutUint32(b[n:], v) }
	copy(b, "FB09")
	p32(4, 8)
	p16(8, 16)
	p16(10, 12)
	p32(12, 2)
	p16(24, 0x125)
	p32(28, 48)
	p32(32, 48)
	p16(36, 0x130)
	p32(40, 96)
	p32(44, uint32(6+len(name)))
	p32(48, 1)
	p16(52, 42)
	p16(54, 0x205)
	p32(68, uint32(size))
	p32(80, uint32(offset))
	p16(84, 1)
	p32(92, 1)
	p32(96, 1)
	b[100] = byte(len(name))
	copy(b[101:], name)
	// Add Pascal-unit metadata as a separate module and names subsection.
	b = b[:len(b)-8]
	moduleOffset := len(b)
	b = append(b, make([]byte, 40)...)
	p16(moduleOffset+4, 1)
	p32(moduleOffset+8, 2)
	p16(moduleOffset+28, 1)
	p16(moduleOffset+30, 1)
	p32(moduleOffset+32, uint32(offset))
	p32(moduleOffset+36, uint32(size))
	const unit = "LabWorkload"
	namesOffset := len(b)
	b = append(b, 1, 0, 0, 0, byte(len(unit)))
	b = append(b, []byte(unit)...)
	b = append(b, 0)
	directory := len(b)
	b = append(b, make([]byte, 40)...)
	p16(directory, 16)
	p16(directory+2, 12)
	p32(directory+4, 2)
	p16(directory+16, 0x120)
	p16(directory+18, 1)
	p32(directory+20, uint32(moduleOffset))
	p32(directory+24, 40)
	p16(directory+28, 0x130)
	p32(directory+32, uint32(namesOffset))
	p32(directory+36, uint32(6+len(unit)))
	p16(26, 1)
	p32(16, uint32(directory))
	b = append(b, make([]byte, 8)...)
	copy(b[len(b)-8:], "FB09")
	p32(len(b)-4, uint32(len(b)))
	return b, nil
}
func run(path string) error {
	image, err := pe.Open(path)
	if err != nil {
		return err
	}
	defer image.Close()
	h, ok := image.OptionalHeader.(*pe.OptionalHeader64)
	if !ok {
		return errors.New("expected owned Windows amd64 workload")
	}
	var data []byte
	if strings.EqualFold(filepath.Base(path), "APLaunchTarget.exe") {
		var begin, end uint64
		for _, symbol := range image.Symbols {
			if symbol.SectionNumber < 1 || int(symbol.SectionNumber) > len(image.Sections) {
				continue
			}
			rva := uint64(image.Sections[symbol.SectionNumber-1].VirtualAddress) + uint64(symbol.Value)
			if symbol.Name == "APHookSum" {
				begin = rva
			}
			if symbol.Name == "APHookSumEnd" {
				end = rva
			}
		}
		if begin == 0 || end <= begin {
			return errors.New("owned native leaf symbols missing")
		}
		// Synthetic alias only: the C routine is not compiled by Delphi.
		line := fmt.Sprintf("%x %d T main.hotspot\n", h.ImageBase+begin, end-begin)
		data, err = fixture(strings.NewReader(line), h.ImageBase, h.BaseOfCode)
	} else {
		var nm []byte
		nm, err = exec.Command("go", "tool", "nm", "-size", path).Output()
		if err == nil {
			data, err = fixture(bytes.NewReader(nm), h.ImageBase, h.BaseOfCode)
		}
	}
	if err != nil {
		return err
	}
	sidecar := strings.TrimSuffix(path, filepath.Ext(path)) + ".tds"
	f, err := os.OpenFile(sidecar, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
	if err != nil {
		return err
	}
	if _, err = f.Write(data); err != nil {
		f.Close()
		return err
	}
	if err = f.Close(); err != nil {
		return err
	}
	loaded, err := symbols.LoadImage(path)
	if err != nil {
		return err
	}
	if loaded.ProcedureCount != 1 {
		return errors.New("fixture failed symbol loader validation")
	}
	return nil
}
func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: tdsfixture <owned-cpulab.exe>")
		os.Exit(1)
	}
	if err := run(os.Args[1]); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
